def transform(grid):
    h, w = grid.shape

    best = None
    for bg in np.unique(grid):
        rows = np.where(np.any(grid != bg, axis=1))[0]
        cols = np.where(np.any(grid != bg, axis=0))[0]
        if len(rows) == 0 or len(cols) == 0:
            continue

        sub = grid[:rows[-1] + 1, :cols[-1] + 1]
        if np.any(sub == bg):
            continue

        area = sub.shape[0] * sub.shape[1]
        if best is None or area > best[0]:
            best = (area, bg, sub)

    if best is None:
        sub = grid
    else:
        sub = best[2]

    ph, pw = sub.shape

    row_period = ph
    for p in range(1, ph + 1):
        ok = True
        for r in range(ph):
            if not np.array_equal(sub[r], sub[r % p]):
                ok = False
                break
        if ok:
            row_period = p
            break

    col_period = pw
    for p in range(1, pw + 1):
        ok = True
        for c in range(pw):
            if not np.array_equal(sub[:, c], sub[:, c % p]):
                ok = False
                break
        if ok:
            col_period = p
            break

    tile = sub[:row_period, :col_period]
    out = np.empty_like(grid)
    for r in range(h):
        for c in range(w):
            out[r, c] = tile[r % row_period, (c + 1) % col_period]

    return out

