def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    seen = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if grid[r, c] != 5 or seen[r, c]:
                continue

            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and grid[nr, nc] == 5:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            rows = [p[0] for p in cells]
            cols = [p[1] for p in cells]
            r0, r1 = min(rows), max(rows)
            c0, c1 = min(cols), max(cols)

            top_gaps = [cc for cc in range(c0, c1 + 1) if grid[r0, cc] == 0]
            if not top_gaps:
                continue

            gap = top_gaps[0]

            for rr in range(r0, r1):
                for cc in range(c0, c1 + 1):
                    if grid[rr, cc] == 0:
                        out[rr, cc] = 2

            left_count = sum(1 for cc in range(c0, gap) if grid[r0, cc] == 5)
            right_count = sum(1 for cc in range(gap + 1, c1 + 1) if grid[r0, cc] == 5)

            line_r = r0 - 1
            if line_r >= 0:
                if right_count > left_count:
                    out[line_r, gap:w] = 2
                else:
                    out[line_r, 0:gap + 1] = 2

    return out

def transform(grid):
