    colors = [c for c in np.unique(grid) if c != 0]

    for c in colors:
        row_full = np.any(np.all(grid == c, axis=1))
        col_full = np.any(np.all(grid == c, axis=0))
        if row_full or col_full:
            return np.array([[c]], dtype=grid.dtype)

def transform(grid):
    h, w = grid.shape
    out = np.zeros((h * 2, w * 2), dtype=int)
    tile = np.array([[1, 2],
                     [2, 1]], dtype=int)
    for r in range(h):
        for c in range(w):
            if grid[r, c] != 0:
                out[2*r:2*r+2, 2*c:2*c+2] = tile
    return out

def transform(grid):
    rows = [i for i in range(grid.shape[0]) if (grid[i] == 0).all()]
    cols = [j for j in range(grid.shape[1]) if (grid[:, j] == 0).all()]
    r, c = rows[0], cols[0]

    blocks = [
        grid[:r, :c],
        grid[:r, c+1:],
        grid[r+1:, :c],
        grid[r+1:, c+1:]
    ]

    patterns = [(b == 1).astype(int) for b in blocks if not (b == 2).any()]
    s = patterns[0] + patterns[1] + patterns[2]

    if (s == 3).any():
        return (s == 2).astype(int)
    return (s == 1).astype(int)

def transform(grid):
    out = grid.copy()

    # Find the guide column: it contains the row colors and has the most
    # distinct non-zero colors.
    best_col = None
    best_key = None
    for c in range(grid.shape[1]):
        vals = grid[:, c]
        nz = vals[vals != 0]
        if len(nz) == 0:
            continue
        key = (len(set(nz.tolist())), len(nz), -c)
        if best_key is None or key > best_key:
            best_key = key
            best_col = c

    if best_col is None:
        return out

    for r in range(grid.shape[0]):
        color = grid[r, best_col]
        if color == 0:
            continue
        for c in range(grid.shape[1]):
            if c != best_col and grid[r, c] != 0:
                out[r, c] = color

    return out

