def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            b = grid[r:r+3, c:c+3]
            if (b[0,0] == 3 and b[0,1] == 3 and b[0,2] == 3 and
                b[1,0] == 3 and b[1,1] == 2 and b[1,2] == 3 and
                b[2,0] == 3 and b[2,1] == 3 and b[2,2] == 3):
                centers.append((r + 1, c + 1))

    def is_two_row(r):
        return all(grid[r, c] in (2, 3) for c in range(w)) and any(grid[r, c] == 2 for c in range(w))

    def is_two_col(c):
        return all(grid[r, c] in (2, 3) for r in range(h)) and any(grid[r, c] == 2 for r in range(h))

    two_rows = [r for r in range(h) if is_two_row(r)]
    two_cols = [c for c in range(w) if is_two_col(c)]

    def stamp_ring(cr, cc):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr, nc] != 3:
                    out[nr, nc] = 1

    for r, c in centers:
        if r in two_rows:
            for rr in range(h):
                if out[rr, c] == 0:
                    out[rr, c] = 1
            for rr in two_rows:
                if rr != r:
                    stamp_ring(rr, c)

        if c in two_cols:
            for cc in range(w):
                if out[r, cc] == 0:
                    out[r, cc] = 1
            for cc in two_cols:
                if cc != c:
                    stamp_ring(r, cc)

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    seen = np.zeros((h, w), dtype=bool)
    boxes = []

    for r in range(h):
        for c in range(w):
            if grid[r, c] == 0 or seen[r, c]:
                continue

            color = grid[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            cells = []

            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and grid[nr, nc] == color:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            boxes.append((min(rs), max(rs), min(cs), max(cs), color))

    add = []
    remove = []

    for i in range(len(boxes)):
        r1a, r2a, c1a, c2a, col_a = boxes[i]
        for j in range(i + 1, len(boxes)):
            r1b, r2b, c1b, c2b, col_b = boxes[j]
            if col_a != col_b:
                continue

            color = col_a

            if c2a < c1b or c2b < c1a:
                if c2a < c1b:
                    left = (r1a, r2a, c1a, c2a)
                    right = (r1b, r2b, c1b, c2b)
                else:
                    left = (r1b, r2b, c1b, c2b)
                    right = (r1a, r2a, c1a, c2a)

                ot = max(left[0], right[0])
                ob = min(left[1], right[1])
                overlap = ob - ot + 1
                gap = right[2] - left[3] - 1

                if overlap >= 3 and gap <= overlap:
                    a = ot + 1
                    b = ob - 1
                    for cc in range(left[3], right[2] + 1):
                        add.append((a, cc, color))
                        add.append((b, cc, color))
                    for rr in range(a + 1, b):
                        remove.append((rr, left[3]))
                        remove.append((rr, right[2]))

            if r2a < r1b or r2b < r1a:
                if r2a < r1b:
                    top = (r1a, r2a, c1a, c2a)
                    bottom = (r1b, r2b, c1b, c2b)
                else:
                    top = (r1b, r2b, c1b, c2b)
                    bottom = (r1a, r2a, c1a, c2a)

                ol = max(top[2], bottom[2])
                orr = min(top[3], bottom[3])
                overlap = orr - ol + 1
                gap = bottom[0] - top[1] - 1

                if overlap >= 3 and gap <= overlap:
                    a = ol + 1
                    b = orr - 1
                    for rr in range(top[1], bottom[0] + 1):
                        add.append((rr, a, color))
                        add.append((rr, b, color))
                    for cc in range(a + 1, b):
                        remove.append((top[1], cc))
                        remove.append((bottom[0], cc))

    for r, c in remove:
        out[r, c] = 0

    for r, c, color in add:
        out[r, c] = color

    return out

